func trap(_ h: [Int]) -> Int {
    var l = 0, r = h.count - 1, leftMax = 0, rightMax = 0, water = 0
    while l < r {
        if h[l] < h[r] {
            leftMax = max(leftMax, h[l]); water += leftMax - h[l]; l += 1
        } else {
            rightMax = max(rightMax, h[r]); water += rightMax - h[r]; r -= 1
        }
    }
    return water
}
